  /* ===== Plan stüdyosu, hafta hedefleri ve geri bildirim (plan-studio.js · features.js) ===== */
  ". Hedef": {"en-US": ". Goal", es: ". Objetivo", "pt-BR": ". Objetivo", fr: ". Objectif", de: ". Ziel", ar: ". الهدف"},
  "01 / 03 · Hedefin": {"en-US": "01 / 03 · Your goal", es: "01 / 03 · Tu objetivo", "pt-BR": "01 / 03 · Seu objetivo", fr: "01 / 03 · Votre objectif", de: "01 / 03 · Dein Ziel", ar: "01 / 03 · هدفك"},
  "03 / 03 · Seviyen": {"en-US": "03 / 03 · Your level", es: "03 / 03 · Tu nivel", "pt-BR": "03 / 03 · Seu nível", fr: "03 / 03 · Votre niveau", de: "03 / 03 · Dein Level", ar: "03 / 03 · مستواك"},
  ". Kontrollü başla.": {"en-US": ". Start under control.", es: ". Empieza con control.", "pt-BR": ". Comece com controle.", fr: ". Commencez avec contrôle.", de: ". Starte kontrolliert.", ar: ". ابدأ بتحكّم."},
