/* ===========================================================================
 * Yardımcılar
 * ========================================================================= */

/** Desteklenen dil kodları: tr, en-US, es, pt-BR, fr, de, ar */
export const FORMA_LANGUAGE_CODES = Object.keys(FORMA_LANGUAGES);

/** Verilen dil kodunun yazı yönü: ar => "rtl", diğerleri => "ltr". */
export const formaDir = (lang) => (FORMA_LANGUAGES[lang] || FORMA_LANGUAGES.tr).dir;

/** Verilen dil kodunun Intl yerel ayarı (tarih/sayı biçimlendirme için). */
export const formaLocale = (lang) => (FORMA_LANGUAGES[lang] || FORMA_LANGUAGES.tr).locale;

/** Kaynak Türkçe metnin sözlükte olup olmadığını söyler. */
export const formaHas = (key) => Object.prototype.hasOwnProperty.call(FORMA_TRANSLATIONS, key);

/** Sözlükte karşılığı bulunan Türkçe kaynak anahtarlar. */
export const FORMA_SOURCE_KEYS = Object.keys(FORMA_TRANSLATIONS);

/**
 * Türkçe kaynak metni hedef dile çevirir.
 * - Sözlükte karşılık yoksa veya dil "tr" ise kaynak metnin kendisi döner.
 * - ${...} ve __v0__ gibi dinamik alanlar metnin içinde aynen korunur;
 *   anahtarlar bu alanları içermez, dinamik değerler çağıran tarafta eklenir.
 */
export function formaT(key, lang) {
  const entry = FORMA_TRANSLATIONS[key];
  if (!entry) return key;
  return entry[lang] || key;
}

/**
 * Ekrandaki metin düğümlerini ve placeholder/aria-label/title/alt özniteliklerini
 * sözlükten yararlanarak çevirir. Metin, anahtarla birebir eşleşmelidir.
 * Yalnızca tarayıcı ortamında çağrılmalıdır.
 */
export function formaTranslateDom(root, lang) {
  if (!root || !FORMA_LANGUAGES[lang] || lang === 'tr') return root;
  const walker = root.ownerDocument.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  let node;
  while ((node = walker.nextNode())) {
    const source = node.nodeValue.trim();
    const entry = FORMA_TRANSLATIONS[source];
    if (!entry || !entry[lang]) continue;
    node.nodeValue = node.nodeValue.replace(source, entry[lang]);
  }
  for (const el of root.querySelectorAll('[placeholder],[aria-label],[title],[alt]')) {
    for (const attr of ['placeholder', 'aria-label', 'title', 'alt']) {
      const raw = el.getAttribute(attr);
      if (!raw) continue;
      const entry = FORMA_TRANSLATIONS[raw.trim()];
      if (entry && entry[lang]) el.setAttribute(attr, entry[lang]);
    }
  }
  root.ownerDocument.documentElement.lang = lang;
  root.ownerDocument.documentElement.dir = formaDir(lang);
  return root;
}

export default FORMA_TRANSLATIONS;

